#!/usr/bin/env python3
"""Surgical upgrade script for PHPSCANNER (thscan) on branch `feature/rce-verify-safe-integration`:

1. Automatically recovers any files that were overwritten by the earlier full-bundle `apply_fixes.py`
   from your git history (`HEAD`, `HEAD~1`, `HEAD~2`, or `origin/feature/rce-verify-safe-integration`)
   so `app/config.py` (`rce_verify_enabled`, `lan_fingerprint_enabled`), `app/main.py`, `app/store.py`,
   `app/scanner/rce_verify.py`, `app/scanner/rce_batch.py`, `app/scanner/lan_fingerprint.py`, etc.
   stay 100% intact.
2. Surgically integrates the 3 features from PHP-NodeJS2Shell:
   - IEEE OUI MAC Vendor Lookup (`app/scanner/mac_vendors.py` + `discovery.py` + `models.py` + UI)
   - Tamper-Evident SHA-256 Hash-Chained Audit Log (`app/audit.py` + `/api/audit` + UI badge)
   - Multi-Vector L3/L4 UDP/ICMP Host Discovery (`app/scanner/discovery.py`)
3. Surgically upgrades the CSV Upload UX/UI & Animations (`static/css/styles.css`, `static/js/csv_import.js`, `static/js/app.js`).
"""
from __future__ import annotations

import pathlib
import re
import subprocess

