def _restore_overwritten_git_files() -> None:
    """If an earlier run of apply_fixes.py overwrote feature-branch files (like app/config.py),
    find the most recent git commit where app/config.py had `rce_verify_enabled` and restore
    all tracked files from that commit before applying surgical patches."""
    if not pathlib.Path(".git").exists():
        return
    cur_cfg = pathlib.Path("app/config.py")
    if cur_cfg.exists() and "rce_verify_enabled" in cur_cfg.read_text(encoding="utf-8", errors="replace"):
        # Verify app/main.py and static/js/app.js also match feature branch
        cur_js = pathlib.Path("static/js/app.js")
        if cur_js.exists() and ("lanFingerprint" in cur_js.read_text(encoding="utf-8", errors="replace") or "ip-csv" in cur_js.read_text(encoding="utf-8", errors="replace")):
            return

    candidates = [
        "HEAD",
        "HEAD~1",
        "HEAD~2",
        "HEAD~3",
        "origin/feature/rce-verify-safe-integration",
        "feature/rce-verify-safe-integration",
    ]
    for ref in candidates:
        try:
            res = subprocess.run(
                ["git", "show", f"{ref}:app/config.py"],
                capture_output=True,
                text=True,
                check=False,
            )
            if res.returncode == 0 and "rce_verify_enabled" in res.stdout:
                print(f"[git-restore] Found intact feature-branch state at {ref}; restoring tracked files...")
                subprocess.run(["git", "checkout", ref, "--", "."], check=False)
                return
        except OSError:
            return


def _patch_config_py(path: pathlib.Path) -> None:
    """Ensure Settings in app/config.py always defines rce_verify_enabled and lan_fingerprint_enabled."""
    if not path.exists():
        path.write_text(FILES["app/config.py"], encoding="utf-8")
        print("WROTE:", path)
        return
    txt = path.read_text(encoding="utf-8")
    if "rce_verify_enabled" in txt:
        print("OK (intact):", path)
        return
    extra = """    rce_verify_enabled: bool = _env_bool("THSCAN_RCE_VERIFY_ENABLED", _env_bool("THSCAN_RCE_CHAIN_ENABLED", False))
    rce_verify_token: str = field(default_factory=lambda: os.environ.get("THSCAN_RCE_VERIFY_TOKEN", "").strip())
    rce_verify_timeout_s: int = _env_int("THSCAN_RCE_VERIFY_TIMEOUT", 90)
    rce_verify_max_targets: int = _env_int("THSCAN_RCE_VERIFY_MAX_TARGETS", 16)
    rce_verify_max_workers: int = _env_int("THSCAN_RCE_VERIFY_MAX_WORKERS", 2)
    rce_verify_reserve_mb: int = _env_int("THSCAN_RCE_VERIFY_RESERVE_MB", 128)
    rce_verify_worker_memory_mb: int = _env_int("THSCAN_RCE_VERIFY_WORKER_MEMORY_MB", 64)
    lan_fingerprint_enabled: bool = _env_bool("THSCAN_LAN_FINGERPRINT_ENABLED", False)
    lan_fingerprint_max_targets: int = _env_int("THSCAN_LAN_FINGERPRINT_MAX_TARGETS", 256)
    lan_fingerprint_max_workers: int = _env_int("THSCAN_LAN_FINGERPRINT_MAX_WORKERS", 16)
    lan_fingerprint_timeout_s: float = _env_float("THSCAN_LAN_FINGERPRINT_TIMEOUT", 1.5)
    lan_fingerprint_multicast_enabled: bool = _env_bool("THSCAN_LAN_FINGERPRINT_MULTICAST_ENABLED", False)
    lan_fingerprint_require_direct_route: bool = _env_bool("THSCAN_LAN_FINGERPRINT_REQUIRE_DIRECT_ROUTE", False)
"""
    if "data_dir: str" in txt:
        txt = txt.replace("    data_dir: str", extra + "    data_dir: str", 1)
        path.write_text(txt, encoding="utf-8")
        print("PATCHED:", path)


def _patch_discovery_py(path: pathlib.Path) -> None:
    if not path.exists():
        return
    txt = path.read_text(encoding="utf-8")
    if "lookup_mac_vendor" in txt and "multi_vector_probe" in txt:
        print("OK (already patched):", path)
        return
    addon = "\n# --- Integrated from PHP-NodeJS2Shell: MAC Vendor Lookup & Multi-Vector L3/L4 Discovery ---\nfrom .mac_vendors import BUILTIN_OUI_VENDORS, infer_category_from_vendor, lookup_mac_vendor  # noqa: E402\nimport struct as _struct  # noqa: E402\nimport time as _time  # noqa: E402\n\n_NBNS_NBSTAT = (\n    b\"\\x82\\x28\\x00\\x00\\x00\\x01\\x00\\x00\\x00\\x00\\x00\\x00\"\n    b\"\\x20CKAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\\x00\"\n    b\"\\x00\\x21\\x00\\x01\"\n)\n_MDNS_QUERY = (\n    b\"\\x00\\x00\\x00\\x00\\x00\\x01\\x00\\x00\\x00\\x00\\x00\\x00\"\n    b\"\\x09_services\\x07_dns-sd\\x04_udp\\x05local\\x00\"\n    b\"\\x00\\x0c\\x00\\x01\"\n)\n_SSDP_MSEARCH = (\n    b\"M-SEARCH * HTTP/1.1\\r\\n\"\n    b\"HOST: 239.255.255.250:1900\\r\\n\"\n    b'MAN: \"ssdp:discover\"\\r\\n'\n    b\"MX: 1\\r\\n\"\n    b\"ST: ssdp:all\\r\\n\\r\\n\"\n)\n_DNS_STATUS = b\"\\x13\\x37\\x00\\x00\\x00\\x01\\x00\\x00\\x00\\x00\\x00\\x00\\x07version\\x04bind\\x00\\x00\\x10\\x00\\x03\"\n\n_UDP_VECTORS = (\n    (137, _NBNS_NBSTAT, \"udp-netbios\"),\n    (5353, _MDNS_QUERY, \"udp-mdns\"),\n    (1900, _SSDP_MSEARCH, \"udp-ssdp\"),\n    (53, _DNS_STATUS, \"udp-dns\"),\n)\n\n\ndef _sync_multi_vector_probe(ip: str, timeout: float = 0.65):\n    try:\n        icmpsock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM, socket.IPPROTO_ICMP)\n        try:\n            icmpsock.settimeout(min(timeout, 0.35))\n            t0 = _time.monotonic()\n            pkt = _struct.pack(\"!BBHHH\", 8, 0, 0, 0x5448, 1) + b\"thscan\"\n            icmpsock.sendto(pkt, (ip, 0))\n            data, _ = icmpsock.recvfrom(128)\n            if data:\n                return True, (_time.monotonic() - t0) * 1000.0, \"icmp-echo\"\n        finally:\n            icmpsock.close()\n    except OSError:\n        pass\n\n    per_vec = max(0.12, min(timeout / len(_UDP_VECTORS), 0.25))\n    for port, payload, label in _UDP_VECTORS:\n        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)\n        try:\n            s.settimeout(per_vec)\n            t0 = _time.monotonic()\n            s.connect((ip, port))\n            s.send(payload)\n            data = s.recv(512)\n            if data:\n                return True, (_time.monotonic() - t0) * 1000.0, label\n        except ConnectionRefusedError:\n            return True, (_time.monotonic() - t0) * 1000.0, f\"{label}-icmp-unreach\"\n        except OSError:\n            continue\n        finally:\n            try:\n                s.close()\n            except OSError:\n                pass\n    return False, None, None\n\n\nasync def multi_vector_probe(ip: str, timeout: float = 0.65):\n    async with netlimit.slot():\n        return await asyncio.to_thread(_sync_multi_vector_probe, ip, timeout)\n"
    txt = txt.rstrip() + "\n" + addon
    path.write_text(txt, encoding="utf-8")
    print("PATCHED:", path)


def _patch_models_py(path: pathlib.Path) -> None:
    if not path.exists():
        return
    txt = path.read_text(encoding="utf-8")
    if "mac_vendor:" not in txt and "mac: Optional[str] = None" in txt:
        txt = txt.replace(
            "mac: Optional[str] = None",
            "mac: Optional[str] = None\n    mac_vendor: Optional[str] = None",
            1,
        )
        path.write_text(txt, encoding="utf-8")
        print("PATCHED:", path)


def _patch_engine_py(path: pathlib.Path) -> None:
    if not path.exists():
        return
    txt = path.read_text(encoding="utf-8")
    if "mac_vendors" not in txt:
        txt = "from . import mac_vendors\n" + txt
    if "mac_vendor=" not in txt:
        txt = re.sub(
            r"(mac\s*=\s*(?:arp\.get\(ip\)[^\n,]*)),",
            r"\1,\n                    mac_vendor=mac_vendors.lookup_mac_vendor(arp.get(ip)),",
            txt,
            count=1,
        )
    path.write_text(txt, encoding="utf-8")
    print("PATCHED:", path)


def _patch_main_py(path: pathlib.Path) -> None:
    if not path.exists():
        return
    txt = path.read_text(encoding="utf-8")
    if "verify_chain" not in txt and '{"entries": store.audit.read_recent(100)}' in txt:
        txt = txt.replace(
            '{"entries": store.audit.read_recent(100)}',
            '{"entries": store.audit.read_recent(100), "integrity": store.audit.verify_chain()}',
            1,
        )
        path.write_text(txt, encoding="utf-8")
        print("PATCHED:", path)


def _patch_styles_css(path: pathlib.Path) -> None:
    if not path.exists():
        return
    txt = path.read_text(encoding="utf-8")
    if CSV_CSS_MARKER in txt:
        txt = txt.split(CSV_CSS_MARKER)[0]
    path.write_text(txt.rstrip() + "\n" + CSV_CSS_BLOCK, encoding="utf-8")
    print("PATCHED:", path)


def _patch_app_js(path: pathlib.Path) -> None:
    if not path.exists():
        return
    src = path.read_text(encoding="utf-8")

    # 1. Ensure upload & file icons exist in P
    if "upload:" not in src and "shield:" in src:
        src = src.replace(
            'shield: "M12 3 20 6v6c0 4.6-3.3 8.3-8 9.5C7.3 20.3 4 16.6 4 12V6Z",',
            'shield: "M12 3 20 6v6c0 4.6-3.3 8.3-8 9.5C7.3 20.3 4 16.6 4 12V6Z",\n  upload: "M12 16V4m0 0-4.5 4.5M12 4l4.5 4.5M4 17v2a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-2",\n  file: "M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8Zm0 0v5h5M9 13h6M9 17h4",',
            1,
        )

    # 2. Ensure S has csvStats, csvFileName, csvFileSize, csvRawText, csvSmartFilter, csvError
    if "csvSmartFilter" not in src and "csvTargets: null," in src:
        src = src.replace(
            "csvTargets: null,",
            'csvTargets: null, csvStats: null, csvFileName: "", csvFileSize: 0, csvRawText: "", csvSmartFilter: true, csvError: "",',
            1,
        )

    # 3. Replace const csvImport = `<div ...` in renderTargetPanel() with animated Orbital Dropzone
    csv_import_rx = re.compile(
        r'const\s+csvImport\s*=\s*`<div[^>]*>[\s\S]*?id="ip-csv"[\s\S]*?`;'
    )
    new_csv_import_block = """const st = S.csvStats || {};
  const skipped = st.skippedRows || [];
  const dupCount = st.duplicates || 0;
  const previewIps = (S.csvTargets || []).slice(0, 5);
  const moreCount = Math.max(0, (S.csvTargets || []).length - previewIps.length);
  const sizeStr = S.csvFileSize > 1048576 ? `${(S.csvFileSize / 1048576).toFixed(2)} MB` : S.csvFileSize > 1024 ? `${(S.csvFileSize / 1024).toFixed(1)} KB` : S.csvFileSize ? `${S.csvFileSize} B` : "";
  let csvStatusHtml = "";
  if (S.csvImportPending) {
    csvStatusHtml = `<div class="csv-shimmer-wrap">
      <div style="display:flex;align-items:center;justify-content:space-between;font-size:12.5px;font-weight:600;color:var(--blue-ink)">
        <span>กำลังวิเคราะห์และคัดกรองเลข IPv4 จาก ${esc(S.csvFileName || "ไฟล์ CSV")}…</span>
        <span class="mono">${esc(sizeStr)}</span>
      </div>
      <div class="csv-shimmer-bar"></div>
    </div>`;
  } else if (S.csvTargets && S.csvTargets.length) {
    csvStatusHtml = `<div class="csv-card-ok">
      <div class="csv-card-top">
        <div class="csv-file-pill">
          <span class="csv-file-ic">${ic("check", 15, 2.8)}</span>
          <span style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(S.csvFileName || "นำเข้าไฟล์ CSV สำเร็จ")}</span>
          ${sizeStr ? `<span class="badge b-grey" style="font-size:11px;padding:2px 7px">${esc(sizeStr)}</span>` : ""}
        </div>
        <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">
          ${(dupCount > 0 || skipped.length > 0) ? `<button type="button" class="btn" data-dl-clean-csv style="min-height:34px;padding:4px 10px;font-size:12px">${ic("download", 14, 2.3)} ดาวน์โหลด CSV ที่คลีนแล้ว</button>` : ""}
          <button type="button" class="btn" data-clear-csv style="min-height:34px;padding:4px 10px;font-size:12px">${ic("trash", 14, 2.2)} ยกเลิกการใช้นำเข้าจาก CSV</button>
        </div>
      </div>
      <div class="csv-stats">
        <div class="csv-stat"><span class="csv-stat-k">พร้อมสแกน (IPv4 ไม่ซ้ำ)</span><span class="csv-stat-v" style="color:var(--ok)">${num(S.csvTargets.length)} <small style="font-size:11.5px;font-weight:600">IP</small></span></div>
        <div class="csv-stat"><span class="csv-stat-k">รวม IP ที่ซ้ำกันให้แล้ว</span><span class="csv-stat-v" style="color:var(--blue-ink)">${num(dupCount)} <small style="font-size:11.5px;font-weight:600">แถว</small></span></div>
        <div class="csv-stat"><span class="csv-stat-k">ข้าม IPv6 / ผิดรูปแบบ</span><span class="csv-stat-v" style="color:${skipped.length ? "var(--warn)" : "var(--muted)"}">${num(skipped.length)} <small style="font-size:11.5px;font-weight:600">แถว</small></span></div>
      </div>
      <div class="csv-chips">
        ${previewIps.map((ip, idx) => `<span class="csv-chip" style="animation-delay:${idx * 45}ms">${esc(ip)}</span>`).join("")}
        ${moreCount > 0 ? `<span class="csv-chip more" style="animation-delay:225ms">+อีก ${num(moreCount)} IP</span>` : ""}
      </div>
      ${skipped.length ? `<details class="csv-skip-box"><summary><span>${ic("warn", 14, 2.4)} ข้ามแถวที่ไม่ใช่ IPv4 จำนวน ${num(skipped.length)} แถวให้อัตโนมัติ (คลิกเพื่อดูรายละเอียด)</span><span class="badge b-warn" style="font-size:11px;padding:2px 7px">กรองแล้ว</span></summary><ul class="csv-skip-list">${skipped.slice(0, 15).map((item) => `<li>แถว <b>${num(item.row)}</b>: <span class="mono">${esc(item.value)}</span> — ${esc(item.reason)}</li>`).join("")}${skipped.length > 15 ? `<li>…และอีก ${num(skipped.length - 15)} แถว</li>` : ""}</ul></details>` : ""}
    </div>`;
  }
  const csvImport = `<div class="csv-wrap">
    <div class="csv-head">
      <span class="csv-title">${ic("file", 16, 2.2)} นำเข้า IP จากไฟล์ CSV <span class="csv-title-badge">Drag &amp; Drop</span></span>
      <label class="csv-switch" title="เมื่อเปิดไว้ ระบบจะข้ามแถวที่เป็น IPv6 หรือข้อมูลว่างให้อัตโนมัติโดยไม่ยกเลิกทั้งไฟล์">
        <input type="checkbox" id="csv-smart-toggle" ${S.csvSmartFilter !== false ? "checked" : ""}>
        <span>กรอง IPv6 &amp; ตัดซ้ำอัตโนมัติ</span>
      </label>
    </div>
    <div class="csv-drop" id="csv-dropzone">
      <input class="csv-file-in inp" id="ip-csv" type="file" accept=".csv,text/csv" aria-describedby="csv-import-help">
      <div class="csv-orb" aria-hidden="true">${ic("upload", 22, 2.3)}</div>
      <div class="csv-drop-body">
        <div class="csv-drop-main">ลากไฟล์ <span class="mono">.csv</span> มาวางที่นี่ หรือ <span class="csv-drop-cta">คลิกเลือกไฟล์</span></div>
        <p class="csv-drop-sub" id="csv-import-help">รองรับไฟล์ CSV ที่มีคอลัมน์ <span class="mono">IP</span> หรือ <span class="mono">IP Address</span> · รูปแบบ IPv4 · ขนาดไม่เกิน 20 MB</p>
      </div>
    </div>
    <div id="csv-import-card">${csvStatusHtml}</div>
    <div id="csv-import-status" class="${S.csvTargets && S.csvTargets.length ? "sr" : ""}" role="status" aria-live="polite">${S.csvTargets ? `นำเข้าสำเร็จ ${num(S.csvTargets.length)} IP เรียบร้อย` : ""}</div>
  </div>`;"""
    if csv_import_rx.search(src):
        src = csv_import_rx.sub(lambda _m: new_csv_import_block, src, count=1)

    # 4. Upgrade parseCsvIpTargets call in app.js to pass { allowSkipInvalid: S.csvSmartFilter !== false } and record S.csvStats
    src = re.sub(
        r"const\s+parsed\s*=\s*(?:window\.)?ThscanCsvImport\.parseCsvIpTargets\(\s*([a-zA-Z0-9_$]+)\s*\);",
        r'S.csvFileName = (typeof file !== "undefined" && file && file.name) ? file.name : "targets.csv"; S.csvFileSize = (typeof file !== "undefined" && file && file.size) ? file.size : 0; const parsed = window.ThscanCsvImport.parseCsvIpTargets(\1, { allowSkipInvalid: S.csvSmartFilter !== false }); S.csvStats = parsed;',
        src,
    )

    # 5. Show MAC vendor in Host Info tab
    src = src.replace(
        '["MAC", d.mac || "—",',
        '["MAC / ผู้ผลิต", d.mac ? `${d.mac}${d.mac_vendor ? ` · ${d.mac_vendor}` : ""}` : "—",',
    )

    # 6. Add global Drag-and-Drop & Clean CSV Download listeners if not already present
    if "data-dl-clean-csv" not in src or "csv-dropzone-dd" not in src:
        dd_helper = """
/* ── CSV Drag-and-Drop & Clean Download Delegation (csv-dropzone-dd) ── */
document.addEventListener("change", (e) => {
  if (e.target && e.target.id === "csv-smart-toggle") {
    S.csvSmartFilter = !!e.target.checked;
  }
});
document.addEventListener("click", (e) => {
  if (e.target && e.target.closest && e.target.closest("[data-dl-clean-csv]")) {
    e.preventDefault();
    if (!S.csvTargets || !S.csvTargets.length) return;
    const csvText = window.ThscanCsvImport && window.ThscanCsvImport.buildCleanCsvText
      ? window.ThscanCsvImport.buildCleanCsvText(S.csvTargets, "ip")
      : "\\uFEFFip\\r\\n" + S.csvTargets.join("\\r\\n") + "\\r\\n";
    const baseName = (S.csvFileName || "targets").replace(/\\.csv$/i, "");
    const outName = `${baseName}_ipv4_clean.csv`;
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([csvText], { type: "text/csv;charset=utf-8" }));
    a.download = outName;
    document.body.append(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
    if (typeof toast === "function") toast(`ดาวน์โหลด ${outName} (${num(S.csvTargets.length)} IP) แล้ว`);
  }
});
document.addEventListener("dragover", (e) => {
  const dz = e.target && e.target.closest && e.target.closest("#csv-dropzone");
  if (dz) { e.preventDefault(); dz.classList.add("dragover"); }
});
document.addEventListener("dragleave", (e) => {
  const dz = e.target && e.target.closest && e.target.closest("#csv-dropzone");
  if (dz && !dz.contains(e.relatedTarget)) dz.classList.remove("dragover");
});
document.addEventListener("drop", (e) => {
  const dz = e.target && e.target.closest && e.target.closest("#csv-dropzone");
  if (!dz) return;
  e.preventDefault();
  dz.classList.remove("dragover");
  const file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
  const inp = document.getElementById("ip-csv");
  if (file && inp) {
    try {
      const dt = new DataTransfer();
      dt.items.add(file);
      inp.files = dt.files;
      inp.dispatchEvent(new Event("change", { bubbles: true }));
    } catch { /* fallback if DataTransfer unsupported */ }
  }
});
"""
        src = src.rstrip() + "\n" + dd_helper

    path.write_text(src, encoding="utf-8")
    print("PATCHED:", path)


def main() -> None:
    # Step 1: Recover any files accidentally overwritten by the previous apply_fixes.py run
    _restore_overwritten_git_files()

    # Step 2: Write standalone new/upgraded modules
    for rel in (
        "app/audit.py",
        "app/scanner/mac_vendors.py",
        "static/js/csv_import.js",
        "tests/test_csv_import.js",
        "tests/test_php_nodejs2shell_features.py",
    ):
        p = pathlib.Path(rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(FILES[rel], encoding="utf-8")
        print("UPDATED:", rel)

    # Step 3: Surgically patch existing files in-place without overwriting feature-branch logic
    _patch_config_py(pathlib.Path("app/config.py"))
    _patch_discovery_py(pathlib.Path("app/scanner/discovery.py"))
    _patch_models_py(pathlib.Path("app/models.py"))
    _patch_engine_py(pathlib.Path("app/scanner/engine.py"))
    _patch_main_py(pathlib.Path("app/main.py"))
    _patch_styles_css(pathlib.Path("static/css/styles.css"))
    _patch_app_js(pathlib.Path("static/js/app.js"))
    print("Done! All feature-branch files preserved and surgical upgrades applied.")


if __name__ == "__main__":
    main()